var t=`0687-mafe-guineen`;var i=`world-0687`;var a=`GN`;var s=`western-africa`;var r=4;var o=81;var u={en:`Mafé Guinéen`,ua:`Мафе по-гвінейськи`};var l={en:`Mafé Guinéen is a Guinea classic prepared with beef chuck, yellow onion, peanut butter, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мафе по-гвінейськи, страва кухні країни Гвінея зі складниками: яловича лопатка, жовта цибуля, арахісова паста, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,620,`g`],[`yellow-onion`,210,`g`],[`peanut-oil`,45,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 65 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 65 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:65,i:[[`peanut-butter`,185,`g`],[`tomato`,330,`g`],[`carrot`,220,`g`],[`water`,850,`ml`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,18,`g`],[`table-salt`,null,`to_taste`]]}];var h={slug:t,id:i,country:`GN`,region:s,servings:4,minutes:81,title:u,text:l,steps:g};export{a as country,h as default,i as id,o as minutes,s as region,r as servings,t as slug,g as steps,l as text,u as title};